<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { ChevronDown } from '@lucide/svelte'; import { cn } from '../../utils.js'; import { useWebPreviewContext } from './context.svelte.js';
  export interface WebPreviewConsoleLog { level: 'log' | 'warn' | 'error'; message: string; timestamp: Date | string | number; }
  interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { logs?: WebPreviewConsoleLog[]; class?: string; children?: Snippet; }
  let { logs = [], class: className = '', children, ...rest }: Props = $props(); const preview = useWebPreviewContext('WebPreviewConsole'); function formatTimestamp(value: Date | string | number): string { const date = value instanceof Date ? value : new Date(value); return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleTimeString(); }
</script>
<div {...rest} class={cn('svadmin-ai-web-part__console', className)} data-slot="web-preview-console"><button type="button" aria-expanded={preview.consoleOpen} onclick={() => preview.setConsoleOpen(!preview.consoleOpen)}><span>Console</span><span>{logs.length}</span><ChevronDown class={preview.consoleOpen ? 'open' : ''} size={14} aria-hidden="true" /></button>{#if preview.consoleOpen}<div role="log" aria-live="polite">{#if logs.length}{#each logs as log, index (`${formatTimestamp(log.timestamp)}-${log.level}-${index}`)}<p class={`svadmin-ai-web-part__log--${log.level}`}><time>{formatTimestamp(log.timestamp)}</time><span>{log.message}</span></p>{/each}{:else}<p class="svadmin-ai-web-part__empty">No console output</p>{/if}{@render children?.()}</div>{/if}</div>
<style>.svadmin-ai-web-part__console { border-top: 1px solid var(--border, currentColor); background: color-mix(in srgb, var(--muted, transparent) 50%, transparent); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }.svadmin-ai-web-part__console > button { display: flex; width: 100%; align-items: center; gap: .45rem; padding: .65rem .75rem; border: 0; background: transparent; color: inherit; text-align: left; font: inherit; font-size: .72rem; cursor: pointer; }.svadmin-ai-web-part__console > button span:nth-child(2) { margin-left: auto; color: var(--muted-foreground, currentColor); }.svadmin-ai-web-part__console > button :global(.open) { transform: rotate(180deg); }.svadmin-ai-web-part__console > button:focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: -2px; }.svadmin-ai-web-part__console > div { display: grid; max-height: 12rem; overflow: auto; gap: .2rem; padding: 0 .75rem .75rem; }.svadmin-ai-web-part__console p { display: flex; gap: .55rem; margin: 0; font-size: .68rem; line-height: 1.45; }.svadmin-ai-web-part__console time, .svadmin-ai-web-part__empty { color: var(--muted-foreground, currentColor); }.svadmin-ai-web-part__log--warn { color: var(--warning, currentColor); }.svadmin-ai-web-part__log--error { color: var(--destructive, currentColor); }</style>
